  this.el<HTMLInputElement>('[data-cast-search]').oninput=()=>{this.filters.set(this.loadedChat||this.chat(),this.el<HTMLInputElement>('[data-cast-search]').value);this.renderRoster();};
  this.el('[data-cast-setup-new]').onclick=()=>this.guardNavigation(()=>this.withLibrary(()=>this.startNew()));
