  this.el('[data-cast-full-appearance]').onclick=()=>{const guidance=this.el('[data-cast-guidance]');guidance.toggleAttribute('data-expanded');this.el('[data-cast-full-appearance]').textContent=guidance.hasAttribute('data-expanded')?'Collapse saved appearance':'Read full saved appearance';};
