  this.el('[data-cast-scan-one]').onclick=()=>this.navigate('sources');this.el('[data-cast-scan]').onclick=()=>this.request({action:'scan',...(this.record()?{characterId:this.record()!.entityId}:{})});
  this.el<HTMLSelectElement>('[data-cast-scan-character]').onchange=()=>this.renderScanSources();this.el<HTMLSelectElement>('[data-cast-scan-source]').onchange=()=>this.previewScan();
  this.el('[data-cast-scan-fill]').onclick=()=>this.fillScan(false);this.el('[data-cast-scan-replace]').onclick=()=>this.fillScan(true);this.el('[data-cast-scan-import]').onclick=()=>this.openScannedCharacter();
