  this.el('[data-cast-setup-outfit-remove]').onclick=()=>{if(!this.session)return;this.readDraft();const id=this.session.outfit;this.session.setup.outfits=this.session.setup.outfits.filter(o=>o.id!==id);if(this.session.setup.defaultOutfitId===id)this.session.setup.defaultOutfitId=null;this.session.outfit='';this.renderOutfits();this.renderDraftStatus();};
  this.el('[data-cast-outfit-art]').onclick=()=>{if(this.session){this.readDraft();this.session.portrait=this.session.outfit;this.navigate('portrait');}};
  this.el<HTMLSelectElement>('[data-cast-portrait-target]').onchange=()=>{if(this.session)this.session.portrait=this.el<HTMLSelectElement>('[data-cast-portrait-target]').value;this.closeGallery();this.renderPortrait();};
  this.el('[data-cast-setup-art]').onclick=()=>this.chooseSetupArt();
  this.el('[data-cast-setup-art-clear]').onclick=()=>this.guardNavigation(()=>{const record=this.record();if(record)this.request({action:'setup_restore',characterId:record.entityId,...(this.session?.portrait?{outfitId:this.session.portrait}:{})});});
  this.el<HTMLSelectElement>('[data-cast-art-variant]').onchange=()=>{this.cancelConfirm();this.variantId=this.el<HTMLSelectElement>('[data-cast-art-variant]').value;this.closeGallery();this.renderVariant();};
