  this.el('[data-cast-art-gallery]').onclick=()=>this.guardNavigation(()=>{const record=this.record();if(record&&this.variantId){this.artworkTarget={chatId:this.loadedChat,characterId:record.entityId,variantId:this.variantId,snapshot:this.snapshot()};this.requestGallery(0);}});
