  this.el('[data-cast-art-forget-character]').onclick=()=>this.guardNavigation(()=>{const record=this.record();if(record)this.confirm(`Remove ${record.name} from this story’s cast library, including setup and portrait pointers? Story text and host gallery images remain.`,()=>this.request({action:'forget',characterId:record.entityId}),'Remove entry');});
  this.el('[data-cast-art-reset]').onclick=()=>this.guardNavigation(()=>this.confirm('Reset this story’s entire character library, including setup and portrait pointers? Story text and host gallery images remain.',()=>this.request({action:'reset'}),'Reset library'));
  this.el('[data-cast-confirm-no]').onclick=()=>this.cancelConfirm();this.el('[data-cast-confirm-yes]').onclick=()=>this.confirmContinue(false);this.el('[data-cast-confirm-save]').onclick=()=>this.confirmContinue(true);
